def cmd_bump(args):
    """Handle the bump subcommand.

    :param args: parsed argparse.Namespace
    :return: string representation of the bumped version
    """
    maptable = {
        'major': 'bump_major',
        'minor': 'bump_minor',
        'patch': 'bump_patch',
        'prerelease': 'bump_prerelease',
        'build': 'bump_build',
    }
    ver = parse_version_info(args.version)
    func = getattr(ver, maptable[args.bump])
    return str(func())


def cmd_check(args):
    """Handle the check subcommand.

    :param args: parsed argparse.Namespace
    :return: string 'True' or 'False'
    """
    return str(VersionInfo.isvalid(args.version))


def cmd_compare(args):
    """Handle the compare subcommand.

    :param args: parsed argparse.Namespace
    :return: string representation of the comparison result
    """
    return str(compare(args.version1, args.version2))
